<?php
if (PHP_SAPI !== 'cli') exit;
define('ABSPATH', __DIR__);
require dirname(__DIR__) . '/includes/class-dt-admin.php';
function check($value, $message) { if (!$value) throw new RuntimeException($message); }
$state = new ReflectionMethod(DT_Admin::class, 'artur_pick_state');
check($state->invoke(null, 10, 10, 20, 84, 76) === 'hit', 'Home winner hit');
check($state->invoke(null, 10, 10, 20, 70, 78) === 'miss', 'Away result misses home pick');
check($state->invoke(null, 20, 10, 20, 70, 78) === 'hit', 'Away winner hit');
check($state->invoke(null, 20, 10, 20, null, null) === 'pending', 'Unresolved game waits');
check($state->invoke(null, 0, 10, 20, 70, 78) === 'missing', 'Missing prediction');
$source=file_get_contents(dirname(__DIR__).'/includes/class-dt-admin.php');
$graphics=file_get_contents(dirname(__DIR__).'/assets/js/admin-artur-graphics.js');
$insights=file_get_contents(dirname(__DIR__).'/includes/class-dt-artur-insights.php');
$insightsJs=file_get_contents(dirname(__DIR__).'/assets/js/admin-artur-insights.js');
check(str_contains($source,'resolved_count') && str_contains($source,'$nextRounds'), 'Default columns use latest resolved and next round');
check(str_contains($source,'Pobierz podsumowanie 16:9') && str_contains($source,'Pobierz zapowiedź 16:9') && str_contains($source,'Pobierz trafienia BONUS 16:9'), 'All infographic actions are available');
check(str_contains($graphics,'1920') && str_contains($graphics,'1080') && str_contains($graphics,'logoUrl'), 'Infographics are 16:9 and include the TypujKosza logo');
check(str_contains($graphics,"rr(ctx,1360,48,500,118,24,C.white)"), 'TypujKosza logo has a white backing panel');
check(!str_contains($graphics,'Typuje:') && !str_contains($graphics,'1920 × 1080  •'), 'Generated graphics do not contain the old footer');
check(str_contains($graphics,"text(ctx,'WYNIK'") && str_contains($graphics,'homeWon?900:650') && str_contains($graphics,'awayWon?900:650'), 'Summary graphic has a score column and emphasizes the winning team');
check(str_contains($source,"'score_home'=>") && str_contains($source,"'score_away'=>"), 'Graphic payload contains separate numeric scores');
check(str_contains($source,"'home_logo'=>") && str_contains($source,"'away_logo'=>"), 'Graphic payload contains both club logos');
check(str_contains($graphics,'preloadMatchLogos') && str_contains($graphics,'teamLogo(ctx'), 'Infographics preload and render club logos');
check(!str_contains($graphics,'TYPOWANIE ZAPISANE'), 'Upcoming-round graphic does not show the saved-prediction label');
check(str_contains($source,'<details class="dt-artur-match') && str_contains($source,'is-winner'), 'Matches are expandable and completed winner is emphasized');
check(!str_contains($insights,'Bilans bezpośredni') && str_contains($insights,'Ostatnie mecze') && str_contains($insights,'3 najbliższe mecze') && str_contains($insights,'Ciekawostki do programu'), 'Preview uses recent and upcoming games without head-to-head');
check(str_contains($insights,'DT_Decka_Stats::parse_pzkosz_game') && str_contains($insights,'season_leaders') && str_contains($insights,"['players']"), 'Official full-season box scores feed player averages');
check(str_contains($insights,'team_record') && str_contains($insights,"return \$wins.'-'.max(0,\$games-\$wins)"), 'Preview team heading includes current W-L record');
check(str_contains($source,'Pobierz w tle wszystkie dane') && str_contains($insights,'process_warm_job') && str_contains($insights,"wp_schedule_single_event"), 'Artur dashboard can warm all visible match data in background');
check(str_contains($insightsJs,'dt_artur_warm_start') && str_contains($insightsJs,'dt_artur_warm_status') && str_contains($insightsJs,'Pobrano '), 'Background warm-up reports progress without blocking the page');
check(str_contains($insights,'game_top_players') && str_contains($insights,"['eval']") && str_contains($insights,'TRIPLE-DOUBLE') && str_contains($insights,'DOUBLE-DOUBLE'), 'Closed-round TOP 3 uses EVAL and points with double-double bonuses');
check(str_contains($insights,'comparison_classes') && str_contains($insights,"\$key==='turnovers'"), 'Team comparison highlights better and worse values and reverses turnovers');
echo "Admin Artur dashboard: OK\n";
